def longest_substring(string):
    """
    time: O(n)
    """
    last_seen = {}
    start = 0  # for single char inputs
    max_length = 0

    for i, char in enumerate(string):
        if char in last_seen:
            start = max(start, last_seen[char] + 1)
        last_seen[char] = i
        max_length = max(max_length, i - start + 1)

    return max_length

